@namespace sv_20aab48b32c84faaa1d37785abdbe9e0.Components.Pages.Board

<div class="task-card">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
    <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move-left" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move-right" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };
}

@namespace sv_20aab48b32c84faaa1d37785abdbe9e0.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@isSaving">Save</button>
        <button class="btn-cancel" @onclick="OnCancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        isSaving = true;
        try
        {
            var task = await TaskService.CreateTaskAsync(title, assignee, priority, dueDate);
            await OnTaskCreated.InvokeAsync(task);
            title = "";
            assignee = "";
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
        finally
        {
            isSaving = false;
        }
    }
}

@namespace sv_20aab48b32c84faaa1d37785abdbe9e0.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => HandleMoveLeft(task)"
                      OnMoveRight="() => HandleMoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm TaskService="TaskService"
                         Status="Status"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => showForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter, EditorRequired] public string? LeftStatus { get; set; }
    [Parameter, EditorRequired] public string? RightStatus { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter, EditorRequired] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private bool showForm;

    private async Task HandleMoveLeft(TaskItem task)
    {
        if (LeftStatus is not null)
            await OnMoveTask.InvokeAsync((task.Id, LeftStatus));
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        if (RightStatus is not null)
            await OnMoveTask.InvokeAsync((task.Id, RightStatus));
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        await OnTaskCreated.InvokeAsync(task);
        showForm = false;
    }
}

@namespace sv_20aab48b32c84faaa1d37785abdbe9e0.Components.Pages.Board

<div class="board-search">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@page "/board"
@namespace sv_20aab48b32c84faaa1d37785abdbe9e0.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <div class="board-loading">Loading tasks...</div>
}
else if (errorMessage is not null)
{
    <div class="board-error">@errorMessage</div>
}
else
{
    <BoardStats Tasks="allTasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Status="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      LeftStatus="@null"
                      RightStatus="In Progress"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="In Progress"
                      Status="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      LeftStatus="To Do"
                      RightStatus="Done"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />

        <KanbanColumn ColumnName="Done"
                      Status="Done"
                      Tasks="GetFilteredTasks("Done")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      LeftStatus="In Progress"
                      RightStatus="@null"
                      OnMoveTask="HandleMoveTask"
                      OnTaskCreated="HandleTaskCreated"
                      TaskService="TaskService" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var taskIndex = allTasks.FindIndex(t => t.Id == move.TaskId);
            if (taskIndex >= 0)
            {
                var old = allTasks[taskIndex];
                allTasks[taskIndex] = old with { Status = move.NewStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        allTasks.Add(task);
    }
}

